#include <iostream>
using namespace std;

int main() {
    int H, B;
    cin >> H >> B;

    if (H <= B) { // すでに頭の重さが体の重さ以下なら
        cout << 0 << endl; // 0 を出力する
    } else { // そうでなければ、
        cout << H - B << endl; // H - B を出力する
    }
    return 0;
}

